#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Deploy the YouTube Description Editor to Vercel for the Owner alone (ADR-0019, ADR-0021).
# Run from the repo root:  bash scripts/deploy-wizard.sh
# Values you enter are remembered in data/deploy.env (gitignored, blocked by the pre-commit guard) so a
# re-run can skip ahead. Every app setting goes to Vercel as a Production-only environment variable.

TOTAL_STAGES=8
ENV_FILE="data/deploy.env"
mkdir -p data
VERCEL="npx --yes vercel@latest"
PY="backend/.venv/Scripts/python"; [[ -x "$PY" ]] || PY="backend/.venv/bin/python"
if [[ ! -x "$PY" ]]; then
  printf 'The backend virtualenv is missing (it generates the secrets). Follow the README Install section first.\n'
  exit 1
fi

# set_vercel_env NAME VALUE replaces NAME in the Vercel project's Production environment.
set_vercel_env() {
  local name="$1" value="$2"
  if printf '%s' "$value" | $VERCEL env add "$name" production --force >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel env %s (Production)\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel env $name: set it in Project → Settings → Environment Variables (Production only)")
    warn "couldn't set $name with the Vercel CLI; set it in the dashboard"
  fi
}

# has_vercel_env NAME: whether the project already has NAME in Production.
has_vercel_env() { $VERCEL env ls production 2>/dev/null | grep -qE "^[[:space:]]*$1[[:space:]]"; }

banner "Deploy the YouTube Description Editor to Vercel"

# ── 1 ───────────────────────────────────────────────────────────────────────
stage "Vercel: sign in and link this repo to a project"
say "The Vercel CLI runs through npx, so there's nothing to install."
step "Sign in when the browser opens (the Hobby plan is fine)."
$VERCEL login
step "Link: answer the prompts to create a NEW project (any name, e.g. yde). Keep the code directory as ./"
$VERCEL link
note "This made a .vercel/ folder; it's gitignored and the pre-commit guard blocks it."
step "In the dashboard, open the project → Settings → Domains and note the production domain."
note "Before the first deploy it may not be listed yet: it's https://<project-name>.vercel.app."
ask YDE_PUBLIC_URL "Production URL (https://<project>.vercel.app):"
YDE_PUBLIC_URL="${YDE_PUBLIC_URL%/}"
write_env YDE_PUBLIC_URL "$YDE_PUBLIC_URL"

# ── 2 ───────────────────────────────────────────────────────────────────────
stage "Database: Neon Postgres from the Vercel Marketplace"
open_url "https://vercel.com/dashboard/stores"
step "Create Database → Neon (Serverless Postgres) → Free plan; pick the region nearest you."
step "Connect it to this project for Production ONLY: untick Preview and Development."
note "A Preview deployment with the production database would run unreviewed code against it (ADR-0021)."
note "Vercel then adds DATABASE_URL (the pooled connection string) to the project for you."
pause "Press Enter once the database is connected"
if has_vercel_env DATABASE_URL; then
  printf '  %s✓%s DATABASE_URL is set in Production\n' "$GREEN" "$RESET"
else
  warn "DATABASE_URL isn't in Production yet. On the store's page, use Connect Project and tick Production."
  pause "Press Enter once it's there"
fi

# ── 3 ───────────────────────────────────────────────────────────────────────
stage "Backups: a private Vercel Blob store"
say "Each Run's JSON Backup copy goes here (ADR-0018). It must be PRIVATE."
if confirm "Create a private Blob store named yde-backups and connect it to this project?"; then
  $VERCEL blob create-store yde-backups --access private --environment production --yes \
    || warn "create-store failed; create it in Storage → Create → Blob → Private, connected to Production only"
fi
if has_vercel_env BLOB_READ_WRITE_TOKEN || has_vercel_env BLOB_STORE_ID; then
  printf '  %s✓%s the Blob store is connected to Production\n' "$GREEN" "$RESET"
else
  open_url "https://vercel.com/dashboard/stores"
  step "Open the yde-backups store → its .env.local (Quickstart) tab → copy BLOB_READ_WRITE_TOKEN."
  ask_secret BLOB_READ_WRITE_TOKEN "Paste BLOB_READ_WRITE_TOKEN:"
  write_env BLOB_READ_WRITE_TOKEN "$BLOB_READ_WRITE_TOKEN"
  set_vercel_env BLOB_READ_WRITE_TOKEN "$BLOB_READ_WRITE_TOKEN"
fi

# ── 4 ───────────────────────────────────────────────────────────────────────
stage "Google: a Web application OAuth client"
say "The app signs you in with Google's web flow, so it needs a Web application client (ADR-0019)."
open_url "https://console.cloud.google.com/apis/credentials"
step "Use the project with the YouTube Data API v3 enabled (see the README's Google Cloud setup)."
step "Create credentials → OAuth client ID → Application type: Web application."
step "Authorised redirect URIs → add both:"
note "    $YDE_PUBLIC_URL/api/auth/callback"
note "    http://localhost:5173/api/auth/callback"
step "Create, then copy the Client ID and the Client secret."
step "Optional, for local mode: Download JSON and save it as data/client_secret.json."
ask GOOGLE_CLIENT_ID "Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Client secret:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
set_vercel_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
set_vercel_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

# ── 5 ───────────────────────────────────────────────────────────────────────
stage "Google: publish the consent screen"
say "In Testing, Google ends the sign-in every 7 days. Published (but not verified), it lasts."
open_url "https://console.cloud.google.com/auth/audience"
step "Publishing status → Publish app → Confirm. Do NOT submit it for verification."
note "When you sign in, Google warns the app isn't verified: choose Advanced → Go to the app. It's your own."
pause "Press Enter once it says In production"

# ── 6 ───────────────────────────────────────────────────────────────────────
stage "Who may sign in, and the app's own secrets"
ask YDE_OWNER_EMAIL "Your Google account's email (the only one allowed in):"
write_env YDE_OWNER_EMAIL "$YDE_OWNER_EMAIL"
YDE_SESSION_SECRET=$(_existing YDE_SESSION_SECRET || "$PY" -c "import secrets; print(secrets.token_urlsafe(48))")
YDE_TOKEN_KEY=$(_existing YDE_TOKEN_KEY || "$PY" -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())")
note "Generated a session secret and a token key (kept from an earlier run if there was one)."
write_env YDE_SESSION_SECRET "$YDE_SESSION_SECRET"
write_env YDE_TOKEN_KEY "$YDE_TOKEN_KEY"
for name in YDE_PUBLIC_URL YDE_OWNER_EMAIL YDE_SESSION_SECRET YDE_TOKEN_KEY; do
  set_vercel_env "$name" "${!name}"
done
warn "Changing YDE_TOKEN_KEY later means signing in again; changing YDE_SESSION_SECRET signs you out."
pause

# ── 7 ───────────────────────────────────────────────────────────────────────
stage "Deploy to production"
say "Vercel builds the frontend, installs the backend, and starts the app (vercel.json, ADR-0021)."
if confirm "Deploy now?"; then
  $VERCEL deploy --prod
else
  SKIPPED+=("Deploy: run  npx vercel@latest deploy --prod")
fi
pause

# ── 8 ───────────────────────────────────────────────────────────────────────
stage "Smoke test"
health=$(curl -s "$YDE_PUBLIC_URL/api/health" || true)
locked=$(curl -s -o /dev/null -w '%{http_code}' "$YDE_PUBLIC_URL/api/videos" || true)
if [[ "$health" == *ok* ]]; then printf '  %s✓%s health: %s\n' "$GREEN" "$RESET" "$health"; else warn "health check failed: $health"; fi
if [[ "$locked" == "401" ]]; then printf '  %s✓%s the API is locked without a session (401)\n' "$GREEN" "$RESET"; else warn "/api/videos returned $locked, expected 401"; fi
open_url "$YDE_PUBLIC_URL"
step "Sign in with $YDE_OWNER_EMAIL: the header should show your channel."
step "In a private window, try another Google account: it must say it isn't allowed."
step "Sync videos. Then review a small edit on 1–2 videos and Apply; keep the tab open until it finishes."
step "Backups: each written video in the run offers Restore (it has a backup in Postgres), and the yde-backups"
note "  Blob store now holds backups/run-<id>.json."
step "Restore one video: its old description comes back on YouTube."
pause "Press Enter when all of that worked (or Ctrl-C and tell Claude what didn't)"

finish
note "Re-run any time: bash scripts/deploy-wizard.sh (values are remembered in $ENV_FILE)."
